// Helper to auto-generate exercises for key practice
function makeKeyEx(keys, count = 3) {
    const base = keys.join('') + ' ';
    const exercises = [];
    const patterns = [
        () => (keys.join('') + ' ').repeat(8).trim(),
        () => keys.flatMap(k => [k+k+k, k+k]).join(' '),
        () => {
            let s = '';
            for (let i = 0; i < 40; i++) s += keys[Math.floor(Math.random() * keys.length)];
            return s.replace(/(.{7})/g, '$1 ').trim();
        }
    ];
    for (let i = 0; i < count; i++) exercises.push(patterns[i % patterns.length]());
    return exercises;
}

